// The dashboard the server serves, and the table the browser demo reuses.
// Everything dynamic is escaped.
import { formatMoney } from "./revrec.mjs";

export const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

export function scheduleTable(rows, currency) {
  const $ = (n) => esc(formatMoney(n, currency));
  const body = [...rows].reverse().map((r) => `<tr${r.future ? ' class="f"' : ""}><td>${esc(r.month)}${r.future ? " <abbr title='Already invoiced, not yet earned'>↗</abbr>" : ""}</td><td>${$(r.opening)}</td><td>+${$(r.billed)}</td><td>-${$(r.recognized)}</td><td>${$(r.closing)}</td></tr>`).join("");
  return `<table><thead><tr><th>Month</th><th>Deferred, opening</th><th>Billed</th><th>Recognised</th><th>Deferred, closing</th></tr></thead><tbody>${body}</tbody></table>`;
}

export function renderDashboard({ company, summary, rows, currency, lastSyncAt, lineCount, skipped }) {
  const $ = (n) => esc(formatMoney(n, currency));
  const tile = (l, v, s = "") => `<div class="t"><div class="l">${esc(l)}</div><div class="v">${v}</div><div class="s">${esc(s)}</div></div>`;
  const s = summary;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(company)} · Rev Rec</title>
<style>:root{font:16px system-ui,sans-serif;color:#1b1f2a;background:#f3f7f5}body{max-width:980px;margin:auto;padding:24px}h1{font-size:1.5rem;color:#0f5132;margin:0 0 4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:16px 0}.t,.card{background:#fff;border:1px solid #cfe0d8;border-radius:12px;padding:14px}.l{font-size:.8rem;color:#3d4f47}.v{font-size:1.5rem;font-weight:800;color:#0f5132}.s,.note{font-size:.84rem;color:#3d4f47}table{border-collapse:collapse;width:100%;font-size:.88rem}th,td{text-align:right;padding:6px 8px;border-bottom:1px solid #e3eee9}th:first-child,td:first-child{text-align:left}tr.f{color:#5b6b64}a{color:#0f5132}</style></head><body>
<h1>${esc(company)} · Rev Rec</h1><p class="note">Last synced ${lastSyncAt ? esc(new Date(lastSyncAt).toISOString().replace("T", " ").slice(0, 16)) + " UTC" : "never"}; ${lineCount} invoice lines. Read-only: this server cannot change anything in Stripe.${skipped ? ` ${skipped} line(s) in another currency were left out.` : ""}</p>
${s ? `<div class="grid">${tile("Deferred revenue now", $(s.deferredNow), "invoiced, not yet earned")}${tile("Recognised last month", s.lastMonth ? $(s.lastMonth.recognized) : "n/a", s.lastMonth ? s.lastMonth.month : "")}${tile("Billed last month", s.lastMonth ? $(s.lastMonth.billed) : "n/a", s.lastMonth ? s.lastMonth.month : "")}${tile("Still to recognise", $(s.backlog), "after this month, already invoiced")}</div>
<div class="card" style="overflow-x:auto">${scheduleTable(rows, currency)}</div>
<p class="note"><a href="/v1/journal.csv">Download journal entries (CSV)</a> · <a href="/v1/schedule">schedule JSON</a>. Import the CSV into your accounting tool or hand it to your accountant.</p>` : `<p>No data yet. Click sync or wait for the first scheduled sync.</p>`}
<p class="note">Revenue is recognised evenly per day over each invoice line's service period, on paid invoices, net of discounts and tax included in the price. Credit notes reduce revenue in the month they are issued. This is a working schedule for your bookkeeping, not accounting, tax or audit advice: check it against your own policy and with your accountant.</p></body></html>`;
}

revrec.mjs.text:
// Revenue recognition from invoice lines. Pure functions, integer minor units.
// A line is {id, billedAt, start, end, amount} with ms timestamps. Revenue is
// recognised evenly per UTC day across [start, end); a line with end <= start
// (a one-off charge, or a credit note) is recognised on its start date.
const DAY = 86400000;
export const monthOf = (ms) => new Date(ms).toISOString().slice(0, 7);
const nextMonth = (m) => { const [y, mo] = m.split("-").map(Number); return mo === 12 ? `${y + 1}-01` : `${y}-${String(mo + 1).padStart(2, "0")}`; };
const monthRange = (a, b) => { const out = []; for (let m = a; m <= b; m = nextMonth(m)) out.push(m); return out; };
export const monthEnd = (m) => { const [y, mo] = m.split("-").map(Number); return Date.UTC(y, mo, 0); };

// {month: minor units} for one line. Day weights; the rounding remainder goes
// to the months with the largest fractional share so the parts sum exactly.
export function spread(line) {
  const amount = Math.round(line.amount);
  const start = Math.floor(line.start / DAY) * DAY;
  const days = line.end > line.start ? Math.max(1, Math.ceil((line.end - start) / DAY)) : 1;
  const perMonth = {};
  for (let i = 0; i < days; i++) { const m = monthOf(start + i * DAY); perMonth[m] = (perMonth[m] || 0) + 1; }
  const sign = amount < 0 ? -1 : 1, abs = Math.abs(amount);
  const parts = Object.entries(perMonth).map(([m, d]) => ({ m, v: Math.floor((abs * d) / days), r: (abs * d) % days }));
  let left = abs - parts.reduce((a, p) => a + p.v, 0);
  for (const p of [...parts].sort((a, b) => b.r - a.r)) { if (left <= 0) break; p.v++; left--; }
  return Object.fromEntries(parts.map((p) => [p.m, sign * p.v]));
}

// Monthly roll-forward. Deferred revenue at month end = billed to date minus
// recognised to date. Negative means revenue recognised before it was billed.
export function schedule(lines, { asOf = Date.now() } = {}) {
  if (!lines.length) return [];
  const billed = {}, rec = {};
  let first = monthOf(asOf), last = monthOf(asOf);
  for (const l of lines) {
    const b = monthOf(l.billedAt);
    billed[b] = (billed[b] || 0) + Math.round(l.amount);
    for (const [m, v] of Object.entries(spread(l))) rec[m] = (rec[m] || 0) + v;
    for (const m of [b, monthOf(l.start)]) if (m < first) first = m;
  }
  const lastRec = Object.keys(rec).sort().pop();
  if (lastRec > last) last = lastRec;
  const out = []; let deferred = 0;
  for (const month of monthRange(first, last)) {
    const opening = deferred, bi = billed[month] || 0, ri = rec[month] || 0;
    deferred = opening + bi - ri;
    out.push({ month, opening, billed: bi, recognized: ri, closing: deferred, future: month > monthOf(asOf) });
  }
  return out;
}

// Revenue already invoiced but not yet earned, by future month (backlog / RPO).
export function backlog(rows, asOf = Date.now()) {
  const cur = monthOf(asOf);
  return rows.filter((r) => r.month > cur && r.recognized !== 0).map((r) => ({ month: r.month, recognized: r.recognized }));
}

// Double-entry rows per month, balanced by construction. Billing: debit the
// receivable/cash account, credit deferred revenue. Recognition: debit
// deferred revenue, credit revenue. Month-end dates, amounts in major units.
export function journal(rows, { cash = "Accounts receivable", deferred = "Deferred revenue", revenue = "Subscription revenue" } = {}) {
  const out = [];
  const major = (n) => (Math.abs(n) / 100).toFixed(2);
  const push = (date, memo, dr, cr, n) => { if (n === 0) return; out.push(n > 0 ? { date, memo, account: dr, debit: major(n), credit: "" } : { date, memo, account: dr, debit: "", credit: major(n) }, n > 0 ? { date, memo, account: cr, debit: "", credit: major(n) } : { date, memo, account: cr, debit: major(n), credit: "" }); };
  for (const r of rows) {
    const date = new Date(monthEnd(r.month)).toISOString().slice(0, 10);
    push(date, `Billings ${r.month}`, cash, deferred, r.billed);
    push(date, `Revenue recognised ${r.month}`, deferred, revenue, r.recognized);
  }
  return out;
}

export function journalCsv(entries) {
  const q = (s) => (/[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s);
  return ["Date,Memo,Account,Debit,Credit", ...entries.map((e) => [e.date, e.memo, e.account, e.debit, e.credit].map(q).join(","))].join("\n") + "\n";
}

export function summary(rows, asOf = Date.now()) {
  const cur = monthOf(asOf);
  const done = rows.filter((r) => r.month < cur);
  const last = done[done.length - 1];
  const now = rows.find((r) => r.month === cur);
  return {
    asOf: cur,
    deferredNow: now ? now.closing : rows.filter((r) => r.month < cur).slice(-1)[0]?.closing ?? 0,
    lastMonth: last ? { month: last.month, recognized: last.recognized, billed: last.billed } : null,
    backlog: backlog(rows, asOf).reduce((a, r) => a + r.recognized, 0),
  };
}

export function formatMoney(minor, currency = "usd") {
  try { return new Intl.NumberFormat("en-US", { style: "currency", currency: String(currency).toUpperCase(), maximumFractionDigits: 0 }).format(minor / 100); }
  catch { return `${(minor / 100).toFixed(0)} ${currency}`; }
}

server.mjs.text:
#!/usr/bin/env node
// Self-hosted deferred-revenue schedule for Stripe. Zero dependencies, read-only key.
//   STRIPE_SECRET_KEY=rk_... ADMIN_KEY=... COMPANY_NAME=Acme node server.mjs
import http from "node:http";
import fs from "node:fs";
import { timingSafeEqual } from "node:crypto";
import { createStripe } from "./stripe.mjs";
import { schedule, summary, journal, journalCsv } from "./revrec.mjs";
import { renderDashboard } from "./page.mjs";

export const newState = () => ({ lines: {}, lastSyncAt: null, currency: null, skipped: 0 });

const eq = (a, b) => { const x = Buffer.from(a), y = Buffer.from(b); return x.length === y.length && timingSafeEqual(x, y); };
export function authorized(header, key) {
  if (!key || !header) return false;
  if (header.startsWith("Bearer ")) return eq(header.slice(7), key);
  if (header.startsWith("Basic ")) return eq(Buffer.from(header.slice(6), "base64").toString().split(":").slice(1).join(":"), key);
  return false;
}

// One pass. The first sync reads everything; later ones re-read the last 3 days
// (lines are keyed by id, so overlap is harmless) and pick up new credit notes.
export async function sync(cfg) {
  const st = cfg.state, now = cfg.now();
  const since = st.lastSyncAt ? Math.floor((st.lastSyncAt - 3 * 86400000) / 1000) : 0;
  const fresh = [...(await cfg.stripe.listLines(since)), ...(await cfg.stripe.listCreditNotes(since))];
  const counts = {};
  for (const l of fresh) counts[l.currency] = (counts[l.currency] || 0) + 1;
  st.currency = cfg.currency || st.currency || Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "usd";
  for (const l of fresh) st.lines[l.id] = l;
  st.skipped = Object.values(st.lines).filter((l) => l.currency !== st.currency).length;
  st.lastSyncAt = now;
  cfg.save();
  return { lines: Object.keys(st.lines).length, added: fresh.length, skipped: st.skipped };
}

const usable = (st) => Object.values(st.lines).filter((l) => l.currency === st.currency);

// cfg: {state, save, stripe, adminKey, company, currency, now, accounts}
export function handler(cfg) {
  let syncing = null;
  const runSync = () => (syncing ||= sync(cfg).finally(() => { syncing = null; }));
  return async (req, res) => {
    const url = new URL(req.url, "http://x");
    const send = (code, body, type = "application/json", extra = {}) => {
      res.writeHead(code, { "content-type": type, "cache-control": "no-store", "referrer-policy": "no-referrer", "x-content-type-options": "nosniff", ...extra });
      res.end(typeof body === "string" ? body : JSON.stringify(body));
    };
    try {
      if (url.pathname === "/healthz") return send(200, "ok\n", "text/plain");
      if (!authorized(req.headers.authorization, cfg.adminKey)) return send(401, "sign in with ADMIN_KEY as the password\n", "text/plain", { "www-authenticate": 'Basic realm="Rev Rec", charset="UTF-8"' });
      const now = cfg.now(), lines = usable(cfg.state);
      const rows = schedule(lines, { asOf: now });
      if (req.method === "GET" && url.pathname === "/") {
        return send(200, renderDashboard({ company: cfg.company || "Your company", summary: rows.length ? summary(rows, now) : null, rows, currency: cfg.state.currency || "usd", lastSyncAt: cfg.state.lastSyncAt, lineCount: lines.length, skipped: cfg.state.skipped }), "text/html; charset=utf-8", { "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'" });
      }
      if (req.method === "GET" && url.pathname === "/v1/schedule") return send(200, { currency: cfg.state.currency, lastSyncAt: cfg.state.lastSyncAt, summary: rows.length ? summary(rows, now) : null, months: rows });
      if (req.method === "GET" && url.pathname === "/v1/journal.csv") {
        const through = url.searchParams.get("through");
        const rs = rows.filter((r) => !r.future && (!through || r.month <= through));
        return send(200, journalCsv(journal(rs, cfg.accounts)), "text/csv; charset=utf-8", { "content-disposition": 'attachment; filename="rev-rec-journal.csv"' });
      }
      if (req.method === "POST" && url.pathname === "/v1/sync") return send(200, await runSync());
      return send(404, "not found\n", "text/plain");
    } catch (e) {
      console.error("request failed:", e.message);
      return send(e.status && e.status < 500 ? 502 : 500, { error: "sync failed; check STRIPE_SECRET_KEY and the server log" });
    }
  };
}

function readJson(path, fallback) {
  try { return JSON.parse(fs.readFileSync(path, "utf8")); } catch (e) { if (e.code === "ENOENT") return fallback; throw e; }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const env = process.env;
  const missing = ["STRIPE_SECRET_KEY", "ADMIN_KEY"].filter((k) => !env[k]);
  if (missing.length) { console.error(`missing env: ${missing.join(", ")}`); process.exit(1); }
  if (env.ADMIN_KEY.length < 12) { console.error("ADMIN_KEY must be at least 12 characters"); process.exit(1); }
  const statePath = env.STATE || "state.json";
  const state = Object.assign(newState(), readJson(statePath, {}));
  const save = () => { fs.writeFileSync(`${statePath}.tmp`, JSON.stringify(state)); fs.renameSync(`${statePath}.tmp`, statePath); };
  const accounts = { cash: env.ACCOUNT_RECEIVABLE || "Accounts receivable", deferred: env.ACCOUNT_DEFERRED || "Deferred revenue", revenue: env.ACCOUNT_REVENUE || "Subscription revenue" };
  const cfg = { state, save, stripe: createStripe({ key: env.STRIPE_SECRET_KEY, maxPages: Number(env.MAX_PAGES) || 500 }), adminKey: env.ADMIN_KEY, company: env.COMPANY_NAME, currency: env.CURRENCY && env.CURRENCY.toLowerCase(), accounts, now: Date.now };
  const h = handler(cfg);
  const tick = () => sync(cfg).then((r) => console.log("synced", JSON.stringify(r)), (e) => console.error("sync failed:", e.message));
  http.createServer(h).listen(Number(env.PORT || 8080), () => {
    console.log(`rev-rec on :${env.PORT || 8080}`);
    tick(); setInterval(tick, Math.max(5, Number(env.SYNC_MINUTES) || 360) * 60000).unref();
  });
}

stripe.mjs.text:
// Read-only Stripe client, no SDK. Restricted key: Invoices read and Credit
// notes read. This code never writes to Stripe.

// One Stripe invoice line -> {id, billedAt, start, end, amount, currency} or null.
// amount = line amount minus discounts, minus tax that is included in the price,
// so recognised revenue excludes sales tax you collect for someone else.
export function normalizeLine(inv, l) {
  if (l.amount === undefined || l.amount === null) return null;
  const discount = (l.discount_amounts || []).reduce((a, d) => a + (d.amount || 0), 0);
  const inclTax = (l.tax_amounts || l.taxes || []).reduce((a, t) => a + (t.inclusive ? t.amount || 0 : 0), 0);
  const p = l.period || {};
  const billedAt = (inv.status_transitions?.paid_at || inv.created) * 1000;
  return { id: l.id, invoice: inv.id, billedAt, start: (p.start ?? inv.created) * 1000, end: (p.end ?? p.start ?? inv.created) * 1000, amount: l.amount - discount - inclTax, currency: inv.currency || l.currency || "usd" };
}

export function normalizeCreditNote(cn) {
  const out = [];
  for (const l of cn.lines?.data || []) {
    const incl = (l.tax_amounts || []).reduce((a, t) => a + (t.inclusive ? t.amount || 0 : 0), 0);
    out.push({ id: `${cn.id}:${l.id}`, invoice: cn.invoice, billedAt: cn.created * 1000, start: cn.created * 1000, end: cn.created * 1000, amount: -((l.amount || 0) - (l.discount_amounts || []).reduce((a, d) => a + (d.amount || 0), 0) - incl), currency: cn.currency || "usd" });
  }
  return out;
}

export function createStripe({ key, fetchImpl = fetch, base = "https://api.stripe.com", maxPages = 500 }) {
  async function get(path) {
    const res = await fetchImpl(`${base}${path}`, { headers: { authorization: `Bearer ${key}` } });
    const json = await res.json().catch(() => ({}));
    if (!res.ok) throw Object.assign(new Error(json?.error?.message || `stripe ${res.status}`), { status: res.status });
    return json;
  }
  async function all(path) {
    const out = []; let after = null;
    for (let page = 0; page < maxPages; page++) {
      const j = await get(`${path}${path.includes("?") ? "&" : "?"}limit=100${after ? `&starting_after=${encodeURIComponent(after)}` : ""}`);
      out.push(...(j.data || []));
      if (!j.has_more || !j.data?.length) return out;
      after = j.data[j.data.length - 1].id;
    }
    throw new Error(`more than ${maxPages * 100} records; raise MAX_PAGES`);
  }
  return {
    // Paid invoices created since `sinceSec` (0 = all), with every line.
    async listLines(sinceSec = 0) {
      const invs = await all(`/v1/invoices?status=paid${sinceSec ? `&created[gte]=${sinceSec}` : ""}`);
      const lines = [];
      for (const inv of invs) {
        let data = inv.lines?.data || [];
        if (inv.lines?.has_more) data = await all(`/v1/invoices/${encodeURIComponent(inv.id)}/lines`);
        for (const l of data) { const n = normalizeLine(inv, l); if (n) lines.push(n); }
      }
      return lines;
    },
    async listCreditNotes(sinceSec = 0) {
      const cns = await all(`/v1/credit_notes${sinceSec ? `?created[gte]=${sinceSec}` : ""}`);
      return cns.filter((c) => c.status !== "void").flatMap(normalizeCreditNote);
    },
  };
}

